bool FEBioFuseStudy::Init()
{
	if (!InitModels())
	{
		feLog("Failed to initialize models.\n");
		return false;
	}

	if (m_strategy == nullptr)
	{
		m_strategy = fecore_new_class<FESolutionStrategy>("FETimeDecoupledStrategy", GetFEModel());
	}
	if (!m_strategy->Init())
	{
		feLog("Failed to initialize solution strategy.\n");
		return false;
	}

	// get the primary FE model
	FEModel* fem = GetFEModel();

	// TODO: make any necessary changes to the model
	fem->AddCallback(coupling_cb, CB_UPDATE_TIME, this);

	// Then, initialize the model
	return fem->Init();
}

