bool FEBioFuseStudy::InitModels()
{
	if (m_fuse.models.empty()) return true;

	FEModel* fem = GetFEModel(); // primary model
	m_fuse.models.SetPrimaryModel(fem);
	string primaryName = m_fuse.models.primaryModel.name;
	if (primaryName.empty() == false)
		fem->SetName(m_fuse.models.primaryModel.name);

	for (SecondaryModel& mdl : m_fuse.models)
	{
		if (!mdl.InitModel())
		{
			std::cerr << "Failed to initialize model: " << mdl.name << std::endl;
			return false;
		}
	}

	// resolve couplings
	for (DataExchange& dex : m_fuse.exchanges)
	{
		if (!dex.InitExchange(m_fuse.models))
		{
			std::cerr << "Failed to initialize data exchange.\n";
			return false;
		}
	}

	// Now that we've been able to read them all in,
	// let's initialize them
	for (SecondaryModel& mdl : m_fuse.models)
	{
		assert(mdl.fem);
		if (mdl.fem->Init() == false)
		{
			std::cerr << "Failed to initialize model :\"" << mdl.name << "\"\n";
			return false;
		}
	}

	FECoreKernel& fecore = FECoreKernel::GetInstance();
	string moduleName;

	// setup plot files
	for (SecondaryModel& mdl : m_fuse.models)
	{
		FEBioPlotFile* xplt = new FEBioPlotFile(mdl.fem.get());

		moduleName = mdl.fem->GetModuleName();
		fecore.SetActiveModule(moduleName.c_str());

		string fileName = mdl.name + ".xplt";
		if (!xplt->Open(fileName.c_str()))
		{
			delete xplt;
			return false;
		}
		mdl.plt = std::shared_ptr<FEBioPlotFile>(xplt);
		mdl.plt->Write(0.f);
	}

	// restore correct module for the primary model
	moduleName = GetFEModel()->GetModuleName();
	fecore.SetActiveModule(moduleName.c_str());

	return true;
}

bool FEBioFuseStudy::RunCoupling()
{
	return m_strategy->RunCoupling(m_fuse);
}

void FEBioFuseStudy::BuildReport(FEBioReport& report)
{
	FEReportSection& outSec = report.AddSection("Output");
	outSec.AddText("The following output files were generated:");
	for (SecondaryModel& mdl : m_fuse.models)
	{
		if (mdl.plt)
		{
			outSec.AddFile(mdl.plt->GetFilename(), mdl.name);
		}
	}
}
